// Берём JSON из предыдущего узла
const choices = $json.choices || [];
if (!choices.length) return [];

const img = choices[0]?.message?.images?.[0];
if (!img) return [];

const dataUrl = img?.image_url?.url || '';
const m = dataUrl.match(/^data:(.+);base64,(.*)$/);
if (!m) return [];

const mimeType = m[1];
const base64 = m[2];
const ext = (mimeType.split('/')[1] || 'png').split(';')[0];
const fileName = `openrouter_${Date.now()}_1.${ext}`;

return [{
  json: {
    index: 1,
    fileName,
    mimeType,
    sizeBase64Chars: base64.length
  },
  binary: {
    data: {
      data: base64,
      fileName,
      mimeType
    }
  }
}];

const res = $('Send a photo message').item.json;
const photo = res?.result?.photo;

if (!Array.isArray(photo) || photo.length === 0) {
  return [{ json: { file_id_max: null, error: 'no photo sizes' } }];
}

// На всякий: выберем по максимальному file_size, fallback — последний элемент
const best = photo.reduce((a, b) => ((a.file_size || 0) >= (b.file_size || 0) ? a : b), photo[photo.length - 1]);

return [{ json: { file_id_max: best.file_id } }];

// Получаем все элементы, которые пришли в узел.
// Это самый надёжный способ получить данные из предыдущего узла.
const items = $input.all();

// Если нет элементов, возвращаем пустой массив, как того требует n8n.
if (items.length === 0) {
  return [];
}

// Выбираем случайный индекс.
const randomIndex = Math.floor(Math.random() * items.length);

// Получаем случайный элемент.
const randomItem = items[randomIndex];

// Возвращаем его в виде массива с одним элементом.
return [randomItem];

